-- PRO311 source candidate. This file is not an installed-schema or UTC provenance receipt.
CREATE FUNCTION public.pro311_huroof_history(ns TEXT, owner_id TEXT, policy_revision TEXT, policy_hash TEXT, p_window JSONB) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$
DECLARE n INTEGER; upper_seq BIGINT; before_seq BIGINT; output JSONB;
BEGIN
 PERFORM public.eng03_03_assert_current(ns,owner_id,policy_revision,policy_hash);
 IF jsonb_typeof(p_window) IS DISTINCT FROM 'object' OR (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(p_window) k) IS DISTINCT FROM ARRAY['before','limit','upper'] OR jsonb_typeof(p_window->'limit') IS DISTINCT FROM 'number' OR (p_window->>'limit') !~ '^([1-9]|[1-4][0-9]|50)$' THEN RAISE EXCEPTION 'INVALID_HISTORY_QUERY'; END IF;
 n:=(p_window->>'limit')::INTEGER;
 IF (p_window->'upper'='null'::JSONB) IS DISTINCT FROM (p_window->'before'='null'::JSONB) THEN RAISE EXCEPTION 'INVALID_HISTORY_CURSOR'; END IF;
 IF p_window->'upper'<>'null'::JSONB THEN
  IF jsonb_typeof(p_window->'upper') IS DISTINCT FROM 'string' OR jsonb_typeof(p_window->'before') IS DISTINCT FROM 'string' OR p_window->>'upper' !~ '^[1-9][0-9]{0,18}$' OR p_window->>'before' !~ '^[1-9][0-9]{0,18}$' OR (p_window->>'upper')::NUMERIC>9223372036854775807 OR (p_window->>'before')::NUMERIC>9223372036854775807 THEN RAISE EXCEPTION 'INVALID_HISTORY_CURSOR'; END IF;
  upper_seq:=(p_window->>'upper')::BIGINT; before_seq:=(p_window->>'before')::BIGINT; IF before_seq>upper_seq THEN RAISE EXCEPTION 'INVALID_HISTORY_CURSOR'; END IF;
 END IF;
 WITH owned AS MATERIALIZED (
  SELECT e."sequence",e."matchId",e."resultVersion",e."resultHash",e."occurredAt",r."matchId" AS joined_result,m."id" AS joined_match
  FROM public."HuroofOwnerHistoryEntry" e
  LEFT JOIN public."HuroofMatchResult" r ON (r."namespace",r."matchId",r."resultVersion",r."ownerFirebaseIdentityId",r."resultHash")=(e."namespace",e."matchId",e."resultVersion",e."ownerFirebaseIdentityId",e."resultHash")
  LEFT JOIN public."HuroofMatch" m ON (m."namespace",m."id",m."roomId",m."ownerFirebaseIdentityId",m."admissionId")=(r."namespace",r."matchId",r."roomId",r."ownerFirebaseIdentityId",r."admissionId")
  WHERE (e."namespace",e."ownerFirebaseIdentityId")=(ns,owner_id)
 ), bounds AS MATERIALIZED (SELECT COALESCE(upper_seq,(SELECT max("sequence") FROM owned)) AS u),
 selected AS MATERIALIZED (SELECT o.* FROM owned o CROSS JOIN bounds b WHERE o."sequence"<=b.u AND (before_seq IS NULL OR o."sequence"<before_seq) ORDER BY o."sequence" DESC LIMIT n+1),
 anchors AS MATERIALIZED (SELECT o.* FROM owned o WHERE o."sequence"=upper_seq OR o."sequence"=before_seq),
 check_data AS (SELECT (SELECT count(*) FROM anchors) AS anchor_count, EXISTS(SELECT 1 FROM selected WHERE joined_result IS NULL OR joined_match IS NULL) OR EXISTS(SELECT 1 FROM anchors WHERE joined_result IS NULL OR joined_match IS NULL) AS bad),
 page AS (SELECT * FROM selected ORDER BY "sequence" DESC LIMIT n)
 SELECT CASE WHEN upper_seq IS NOT NULL AND ((SELECT count(*) FROM anchors WHERE "sequence"=upper_seq)<>1 OR (SELECT count(*) FROM anchors WHERE "sequence"=before_seq)<>1) THEN jsonb_build_object('fault','INVALID_CURSOR')
 WHEN (SELECT bad FROM check_data) THEN jsonb_build_object('fault','DATA_UNAVAILABLE') ELSE jsonb_build_object('rows',COALESCE((SELECT jsonb_agg(jsonb_build_object('sequence',"sequence"::TEXT,'matchId',"matchId",'resultVersion',"resultVersion"::TEXT,'occurredAt',to_char("occurredAt",'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) ORDER BY "sequence" DESC) FROM page),'[]'::JSONB),'upper',(SELECT u::TEXT FROM bounds),'hasMore',(SELECT count(*)>n FROM selected)) END INTO output;
 IF output ? 'fault' THEN RAISE EXCEPTION 'HISTORY_UNAVAILABLE'; END IF; RETURN output;
END $$;

CREATE FUNCTION public.pro311_huroof_result(ns TEXT, owner_id TEXT, policy_revision TEXT, policy_hash TEXT, match_id TEXT, result_version BIGINT) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$
DECLARE output JSONB;
BEGIN
 -- Held draft below: no accepted resource bound covers complete raw semantic
 -- artifact hashing, UTF-8 conversion and JSONB expansion. Deny before reads.
 RAISE EXCEPTION 'RESULT_RESOURCE_UNAVAILABLE';
 PERFORM public.eng03_03_assert_current(ns,owner_id,policy_revision,policy_hash);
 IF match_id IS NULL OR match_id !~ '^[A-Za-z0-9_-]{1,128}$' OR result_version IS NULL OR result_version<1 THEN RAISE EXCEPTION 'RESULT_UNAVAILABLE'; END IF;
 WITH material AS MATERIALIZED (
  SELECT r.*,e."occurredAt",a."rawBytes",a."byteLength",a."serialization",ev."eventType",m."id" AS valid_match,
    prior."resultHash" AS prior_hash
  FROM public."HuroofMatchResult" r
  LEFT JOIN public."HuroofOwnerHistoryEntry" e ON (e."namespace",e."ownerFirebaseIdentityId",e."matchId",e."resultVersion",e."resultHash")=(r."namespace",r."ownerFirebaseIdentityId",r."matchId",r."resultVersion",r."resultHash")
  LEFT JOIN public."HuroofMatch" m ON (m."namespace",m."id",m."roomId",m."ownerFirebaseIdentityId",m."admissionId")=(r."namespace",r."matchId",r."roomId",r."ownerFirebaseIdentityId",r."admissionId")
  LEFT JOIN public."HuroofEvent" ev ON (ev."namespace",ev."roomId",ev."sequence",ev."id",ev."matchId")=(r."namespace",r."roomId",r."terminalSequence",r."terminalEventId",r."matchId")
  LEFT JOIN public."HuroofRawArtifact" a ON (a."namespace",a."id",a."contentHash")=(r."namespace",r."rawArtifactId",r."resultHash")
  LEFT JOIN public."HuroofMatchResult" prior ON (prior."namespace",prior."matchId",prior."ownerFirebaseIdentityId",prior."resultVersion",prior."resultHash")=(r."namespace",r."matchId",r."ownerFirebaseIdentityId",r."previousVersion",r."previousHash")
  WHERE (r."namespace",r."ownerFirebaseIdentityId",r."matchId",r."resultVersion")=(ns,owner_id,match_id,result_version)
 ), verified AS MATERIALIZED (
  SELECT *,CASE WHEN "rawBytes" IS NOT NULL AND "byteLength">=1 AND octet_length("rawBytes")="byteLength" AND encode(int4_crypto.digest("rawBytes",'sha256'),'hex')="resultHash" AND "serialization"='huroof-command-result-v1' THEN convert_from("rawBytes",'UTF8')::JSONB ELSE NULL END AS semantic FROM material
 )
 SELECT CASE WHEN count(*)<>1 OR bool_or("occurredAt" IS NULL OR valid_match IS NULL OR "eventType" IS DISTINCT FROM 'FINISHED' OR semantic IS NULL OR (result_version=1 AND ("previousVersion" IS NOT NULL OR "previousHash" IS NOT NULL)) OR (result_version>1 AND ("previousVersion" IS DISTINCT FROM result_version-1 OR prior_hash IS DISTINCT FROM "previousHash"))) THEN NULL ELSE jsonb_build_object('schemaVersion',1,'matchId',match_id,'resultVersion',result_version::TEXT,'occurredAt',to_char(min("occurredAt"),'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'questionScores',min(semantic::TEXT)::JSONB->'questionScores','roundWins',min(semantic::TEXT)::JSONB->'match'->'roundWins','matchWinner',COALESCE(min(semantic::TEXT)::JSONB->'match'->'matchWinner','null'::JSONB),'matchWinReason',COALESCE(min(semantic::TEXT)::JSONB->'match'->'matchWinReason','null'::JSONB),'endedWithoutWinner',min(semantic::TEXT)::JSONB->'endedWithoutWinner') END INTO output FROM verified;
 IF output IS NULL THEN RAISE EXCEPTION 'RESULT_UNAVAILABLE'; END IF; RETURN output;
END $$;

-- Enta original result: identity and the unresolved historical UTC proof are
-- checked before the single data statement. The proof guard currently denies.
CREATE FUNCTION public.pro311_enta_original_result(ns TEXT, project TEXT, uid TEXT, target_id TEXT) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$
DECLARE owner_id TEXT; output JSONB;
BEGIN
 owner_id:=public.int6_enta_identity(ns,project,uid)->>'id';
 PERFORM public.e3_comp_history_utc_gate();
 IF target_id IS NULL OR target_id !~ '^[A-Za-z0-9_-]{1,128}$' THEN RAISE EXCEPTION 'RESULT_UNAVAILABLE'; END IF;
 WITH owned_base AS MATERIALIZED (
  SELECT g."id",g."firebaseIdentityId",g."admissionId",g."catalogReleaseId",g."gameFormat",g."executionFormat",g."mode",g."status",g."winnerTeamId",g."isTie",
   a."id" AS admission_join,a."engine",a."state" AS admission_state,a."requestVersion",rt."gameId" AS runtime_join,rt."version",rt."state" AS runtime_state,rt."setup",rt."setupHash",rt."teamOrder",rt."resultReason",rt."unplayedCount",p."rules",pin."clientBinding",pin."clientHash",
   result."payload",result."resultHash",result."terminalRevision",result."terminalEventId",result."authorityEventId",result."predecessorVersion",result."predecessorHash",result."bindingId",result."bindingHash"
  FROM public."Game" g
  LEFT JOIN public."Admission" a ON (a."id",a."firebaseIdentityId")=(g."admissionId",g."firebaseIdentityId")
  LEFT JOIN public."GameRuntime" rt ON rt."gameId"=g."id"
  LEFT JOIN public."E3PhysicalProfile" p ON (p."protocol",p."format",p."mode")=(a."requestVersion",g."executionFormat",g."mode")
  LEFT JOIN public."EntaExecutionPin" pin ON (pin."gameId",pin."firebaseIdentityId")=(g."id",g."firebaseIdentityId")
  LEFT JOIN public."EngineMatchResult" result ON (result."gameId",result."ownerIdentityId",result."admissionId",result."resultVersion")=(g."id",g."firebaseIdentityId",g."admissionId",1)
  WHERE (g."id",g."firebaseIdentityId")=(target_id,owner_id)
 ), ordered_participants AS MATERIALIZED (
  SELECT b."id" AS game_id,o.team_id,o.ordinal,t."id" AS joined_team,t."name",t."score",b."setup"->'teams'->((o.ordinal-1)::INTEGER)->>'name' AS original_name
  FROM owned_base b CROSS JOIN LATERAL unnest(b."teamOrder") WITH ORDINALITY o(team_id,ordinal)
  LEFT JOIN public."Team" t ON (t."gameId",t."id")=(b."id",o.team_id)
 ), adjudications23 AS MATERIALIZED (
  SELECT b."id" AS game_id,e."questionId",e."teamId",e."ruling",e."sequence",q."id" AS joined_question,m."questionRevisionId" AS joined_membership,qr."id" AS joined_revision,qr."points",qr."engine",qr."mode" AS revision_mode,qr."modality",seal."questionRevisionId" AS joined_seal
  FROM owned_base b JOIN public."GameEvent" e ON e."gameId"=b."id" AND e."type"='ADJUDICATE'
  LEFT JOIN public."GameQuestion" q ON (q."gameId",q."id")=(e."gameId",e."questionId") AND q."catalogReleaseId"=b."catalogReleaseId"
  LEFT JOIN public."CatalogReleaseQuestion" m ON (m."catalogReleaseId",m."questionRevisionId")=(q."catalogReleaseId",q."questionRevisionId")
  LEFT JOIN public."QuestionRevision" qr ON (qr."id",qr."contentHash")=(m."questionRevisionId",m."questionContentHash")
  LEFT JOIN public."QuestionRevisionSeal" seal ON (seal."questionRevisionId",seal."contentHash")=(qr."id",qr."contentHash")
 ), postings4 AS MATERIALIZED (
  SELECT b."id" AS game_id,p."id",p."teamId",p."delta",p."before",p."after",p."rulesVersion",e."id" AS joined_event,e."sequence",p."roundId",p."itemId",e."roundId" AS event_round,rr."id" AS joined_round,ri."itemId" AS joined_item,
   lag(p."after") OVER (PARTITION BY b."id",p."teamId" ORDER BY e."sequence",p."id" COLLATE "C") AS previous_after
  FROM owned_base b JOIN public."RoundScorePosting" p ON p."gameId"=b."id"
  LEFT JOIN public."RoundAuthorityEvent" e ON (e."id",e."gameId",e."roundId")=(p."eventId",p."gameId",p."roundId") LEFT JOIN public."GameRound" rr ON (rr."gameId",rr."id")=(p."gameId",p."roundId") LEFT JOIN public."RoundItemPin" ri ON (ri."roundId",ri."itemId")=(p."roundId",p."itemId")
 ), terminals AS MATERIALIZED (
  SELECT b."id" AS game_id,
   (SELECT count(*) FROM public."GameEvent" e WHERE e."gameId"=b."id" AND e."type"='FINISH' AND e."actorFirebaseIdentityId"=owner_id) AS legacy_count,
   (SELECT max(e."sequence") FROM public."GameEvent" e WHERE e."gameId"=b."id" AND e."type"='FINISH' AND e."actorFirebaseIdentityId"=owner_id) AS legacy_sequence,
   (SELECT count(*) FROM public."RoundAuthorityEvent" e WHERE e."gameId"=b."id" AND e."type"='FINISH' AND e."ownerIdentityId"=owner_id AND e."authorityKind"='HOST' AND e."authorityGrantId" IS NULL AND e."authorityGeneration" IS NULL AND e."assignmentId" IS NULL AND e."systemOperation" IS NULL AND e."pauseReason" IS NULL AND e."roundId" IS NULL) AS authority_count,
   (SELECT max(e."sequence") FROM public."RoundAuthorityEvent" e WHERE e."gameId"=b."id" AND e."type"='FINISH' AND e."ownerIdentityId"=owner_id AND e."authorityKind"='HOST' AND e."authorityGrantId" IS NULL AND e."authorityGeneration" IS NULL AND e."assignmentId" IS NULL AND e."systemOperation" IS NULL AND e."pauseReason" IS NULL AND e."roundId" IS NULL) AS authority_sequence
  FROM owned_base b
 ), reconstructed AS MATERIALIZED (
  SELECT b.*,t.legacy_count,t.legacy_sequence,t.authority_count,t.authority_sequence,
   CASE WHEN b."requestVersion"=5 THEN b."payload"->>'reason' WHEN b."requestVersion"=4 AND b."resultReason"='ALL_QUESTIONS_PLAYED' THEN 'ALL_ROUNDS' ELSE b."resultReason" END AS original_reason,
   CASE WHEN b."requestVersion"=5 THEN b."payload"->'unplayedCount' ELSE to_jsonb(b."unplayedCount") END AS original_unplayed,
   CASE WHEN b."requestVersion"=5 THEN b."payload"->>'outcome'='UNRESOLVED_TIE' ELSE b."isTie" END AS original_tie,
   (SELECT jsonb_agg(jsonb_build_object('name',op.original_name,'score',CASE WHEN b."requestVersion"=5 THEN (CASE WHEN public.int5b_json_integer(b."payload"->'scores'->((op.ordinal-1)::INTEGER)->'score',-2147483648,2147483647) THEN (b."payload"->'scores'->((op.ordinal-1)::INTEGER)->>'score')::INTEGER ELSE NULL END) WHEN b."requestVersion" IN (2,3) THEN (SELECT COALESCE(sum(a."points"::BIGINT),0) FROM adjudications23 a WHERE a.game_id=b."id" AND a."ruling"='CORRECT' AND a."teamId"=op.team_id) ELSE (SELECT COALESCE(sum(p."delta"::BIGINT),0) FROM postings4 p WHERE p.game_id=b."id" AND p."teamId"=op.team_id) END,'winner',CASE WHEN b."requestVersion"=5 THEN (b."payload"->'winnerParticipantIds') ? op.team_id ELSE op."score"=(SELECT max(t2."score") FROM public."Team" t2 WHERE t2."gameId"=b."id") END) ORDER BY op.ordinal) FROM ordered_participants op WHERE op.game_id=b."id") AS teams,
   COALESCE(b.admission_join IS NOT NULL AND b.runtime_join IS NOT NULL AND b."gameFormat"='FIREBASE_PINNED' AND b."engine"='ENTA' AND b.admission_state='COMMITTED' AND (b."requestVersion",b."mode",b."executionFormat",b."rules") IN ((2,'CLASSIC','TIER_BOARD','enta-classic-2'),(3,'CLASSIC','TIER_BOARD','enta-classic-3'),(3,'KIDS','TIER_BOARD','enta-kids-3'),(4,'CLASSIC','MIXED_BOARD','enta-format-1'),(4,'LIST','STANDALONE_LIST','enta-format-1'),(4,'ACTING','STANDALONE_ACTING','enta-format-1'),(5,'CLASSIC','TIER_BOARD','enta-competitive-1'),(5,'CLASSIC','MIXED_BOARD','enta-competitive-1'),(5,'LIST','STANDALONE_LIST','enta-competitive-1'),(5,'ACTING','STANDALONE_ACTING','enta-competitive-1')) AND b."status"='FINISHED' AND b.runtime_state='FINISHED' AND cardinality(b."teamOrder") BETWEEN 2 AND 4 AND jsonb_typeof(b."setup"->'teams')='array' AND (CASE WHEN jsonb_typeof(b."setup"->'teams')='array' THEN jsonb_array_length(b."setup"->'teams') ELSE -1 END)=cardinality(b."teamOrder") AND b."setupHash"=public.int6_enta_hash(b."setup") AND (b."mode" NOT IN ('KIDS','LIST','ACTING') OR cardinality(b."teamOrder")=2)
    AND (SELECT count(*) FROM ordered_participants op WHERE op.game_id=b."id")=cardinality(b."teamOrder") AND (SELECT count(DISTINCT op.team_id) FROM ordered_participants op WHERE op.game_id=b."id")=cardinality(b."teamOrder") AND (SELECT count(*) FROM public."Team" x WHERE x."gameId"=b."id")=cardinality(b."teamOrder") AND NOT EXISTS(SELECT 1 FROM ordered_participants op WHERE op.game_id=b."id" AND (op.joined_team IS NULL OR op."name" IS DISTINCT FROM op.original_name OR public.int6_enta_valid_text(to_jsonb(op.original_name),2,22) IS NOT TRUE))
    AND CASE WHEN b."requestVersion" IN (2,3) THEN t.legacy_count=1 AND t.legacy_sequence=b."version" AND EXISTS(SELECT 1 FROM public."GameEvent" f WHERE f."gameId"=b."id" AND f."sequence"=t.legacy_sequence AND f."resultReason" IS NOT DISTINCT FROM b."resultReason" AND f."unplayedCount" IS NOT DISTINCT FROM b."unplayedCount") AND b."resultReason" IN ('ALL_QUESTIONS_PLAYED','HOST_ENDED') AND ((b."resultReason"='HOST_ENDED')=(b."unplayedCount">0)) AND b."unplayedCount" BETWEEN 0 AND CASE WHEN b."mode"='KIDS' THEN 6 ELSE 36 END AND b."isTie"=((SELECT count(*) FROM public."Team" x WHERE x."gameId"=b."id" AND x."score"=(SELECT max(z."score") FROM public."Team" z WHERE z."gameId"=b."id"))>1) AND b."winnerTeamId" IS NOT DISTINCT FROM (SELECT CASE WHEN count(*)=1 THEN min(x."id") ELSE NULL END FROM public."Team" x WHERE x."gameId"=b."id" AND x."score"=(SELECT max(z."score") FROM public."Team" z WHERE z."gameId"=b."id")) AND NOT EXISTS(SELECT 1 FROM adjudications23 a WHERE a.game_id=b."id" AND (a."sequence">=t.legacy_sequence OR a.joined_question IS NULL OR a.joined_membership IS NULL OR a.joined_revision IS NULL OR a.joined_seal IS NULL OR a."engine"<>'ENTA' OR a."modality"<>'classic' OR (a."revision_mode" NOT IN ('CLASSIC','KIDS') OR (b."mode"='CLASSIC' AND a."revision_mode"<>'CLASSIC')) OR a."points" NOT IN (200,400,600) OR NOT ((a."ruling"='CORRECT' AND EXISTS(SELECT 1 FROM ordered_participants op WHERE op.game_id=b."id" AND op.team_id=a."teamId")) OR (a."ruling"='NO_SCORE' AND a."teamId" IS NULL)))) AND NOT EXISTS(SELECT 1 FROM adjudications23 a WHERE a.game_id=b."id" GROUP BY a."questionId" HAVING count(*)<>1) AND (SELECT count(*) FROM public."GameQuestion" q WHERE q."gameId"=b."id")-(SELECT count(*) FROM adjudications23 a WHERE a.game_id=b."id")=b."unplayedCount" AND NOT EXISTS(SELECT 1 FROM ordered_participants op WHERE op.game_id=b."id" AND op."score"::BIGINT IS DISTINCT FROM (SELECT COALESCE(sum(a."points"::BIGINT),0) FROM adjudications23 a WHERE a.game_id=b."id" AND a."ruling"='CORRECT' AND a."teamId"=op.team_id))
     WHEN b."requestVersion"=4 THEN b."clientBinding"->'setup' IS NOT DISTINCT FROM b."setup" AND b."clientHash"=public.int6_enta_hash(b."clientBinding") AND t.authority_count=1 AND (SELECT count(*) FROM public."RoundAuthorityEvent" f WHERE f."gameId"=b."id" AND f."type"='FINISH')=1 AND t.authority_sequence=b."version" AND b."resultReason" IN ('ALL_QUESTIONS_PLAYED','HOST_ENDED') AND ((b."resultReason"='HOST_ENDED')=(b."unplayedCount">0)) AND b."unplayedCount" BETWEEN 0 AND CASE WHEN b."executionFormat" IN ('STANDALONE_LIST','STANDALONE_ACTING') THEN 4 ELSE 36 END AND (SELECT count(*) FROM public."GameRound" rr WHERE rr."gameId"=b."id") BETWEEN 1 AND CASE WHEN b."executionFormat" IN ('STANDALONE_LIST','STANDALONE_ACTING') THEN 4 ELSE 36 END AND NOT EXISTS(SELECT 1 FROM public."GameRound" rr WHERE rr."gameId"=b."id" AND (
 public.int6_enta_exact_keys(rr."state",ARRAY['id','questionId','ordinal','pin','state','version','scoringTeamId','turnDeadline','overallDeadline','remainingTurn','remainingOverall','revealed','assignment','consumed','reason']) IS NOT TRUE
 OR jsonb_typeof(rr."state"->'state') IS DISTINCT FROM 'string' OR COALESCE(rr."state"->>'state' NOT IN ('READY','RUNNING','PAUSED','RESOLVED'),TRUE)
 OR public.int5b_json_integer(rr."state"->'version',0,2000000000) IS NOT TRUE OR jsonb_typeof(rr."state"->'revealed') IS DISTINCT FROM 'boolean' OR jsonb_typeof(rr."state"->'consumed') IS DISTINCT FROM 'array'
 OR jsonb_typeof(rr."state"->'id') IS DISTINCT FROM 'string' OR jsonb_typeof(rr."state"->'questionId') IS DISTINCT FROM 'string' OR public.int5b_json_integer(rr."state"->'ordinal',0,35) IS NOT TRUE OR jsonb_typeof(rr."state"->'pin') IS DISTINCT FROM 'object' OR jsonb_typeof(rr."pin") IS DISTINCT FROM 'object' OR rr."state"->>'id' IS DISTINCT FROM rr."id" OR rr."state"->>'questionId' IS DISTINCT FROM rr."gameQuestionId" OR rr."state"->'ordinal' IS DISTINCT FROM to_jsonb(rr."ordinal") OR rr."state"->'pin' IS DISTINCT FROM rr."pin" OR COALESCE(jsonb_typeof(rr."state"->'scoringTeamId') NOT IN ('null','string'),TRUE) OR (jsonb_typeof(rr."state"->'scoringTeamId')='string' AND NOT EXISTS(SELECT 1 FROM ordered_participants op WHERE op.game_id=b."id" AND op.team_id=(rr."state"->>'scoringTeamId'))) OR (rr."state"->'reason' IS DISTINCT FROM 'null'::JSONB AND (jsonb_typeof(rr."state"->'reason') IS DISTINCT FROM 'string' OR COALESCE(rr."state"->>'reason' NOT IN ('HOST_CLOSED','ALL_ITEMS','TIME_EXPIRED','ADJUDICATED'),TRUE)))
 OR (rr."state"->'assignment' IS DISTINCT FROM 'null'::JSONB AND (public.int6_enta_exact_keys(rr."state"->'assignment',ARRAY['id','teamId','playerIndex','itemId','generation']) IS NOT TRUE OR public.int5b_json_integer(rr."state"->'assignment'->'playerIndex',0,7) IS NOT TRUE OR public.int5b_json_integer(rr."state"->'assignment'->'generation',1,2000000000) IS NOT TRUE))
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(rr."state"->'consumed')='array' THEN rr."state"->'consumed' ELSE '[]'::JSONB END) item WHERE public.int6_enta_exact_keys(item,ARRAY['itemId','teamId','eventId']) IS NOT TRUE)
 OR COALESCE(jsonb_typeof(rr."state"->'turnDeadline') NOT IN ('null','number'),TRUE) OR COALESCE(jsonb_typeof(rr."state"->'overallDeadline') NOT IN ('null','number'),TRUE)
 OR COALESCE(jsonb_typeof(rr."state"->'remainingTurn') NOT IN ('null','number'),TRUE) OR COALESCE(jsonb_typeof(rr."state"->'remainingOverall') NOT IN ('null','number'),TRUE)
)) AND b."unplayedCount"=(SELECT count(*) FROM public."GameRound" rr WHERE rr."gameId"=b."id" AND rr."state"->>'state'<>'RESOLVED') AND b."isTie"=((SELECT count(*) FROM public."Team" x WHERE x."gameId"=b."id" AND x."score"=(SELECT max(z."score") FROM public."Team" z WHERE z."gameId"=b."id"))>1) AND b."winnerTeamId" IS NOT DISTINCT FROM (SELECT CASE WHEN count(*)=1 THEN min(x."id") ELSE NULL END FROM public."Team" x WHERE x."gameId"=b."id" AND x."score"=(SELECT max(z."score") FROM public."Team" z WHERE z."gameId"=b."id")) AND NOT EXISTS(SELECT 1 FROM postings4 p WHERE p.game_id=b."id" AND (p.joined_event IS NULL OR p.joined_round IS NULL OR (p."itemId" IS NOT NULL AND p.joined_item IS NULL) OR p."sequence">=t.authority_sequence OR p."rulesVersion"<>'enta-format-1' OR p."before"::BIGINT IS DISTINCT FROM COALESCE(p.previous_after::BIGINT,0) OR p."after"::BIGINT-p."before"::BIGINT<>p."delta"::BIGINT OR NOT EXISTS(SELECT 1 FROM ordered_participants op WHERE op.game_id=b."id" AND op.team_id=p."teamId"))) AND NOT EXISTS(SELECT 1 FROM postings4 p WHERE p.game_id=b."id" GROUP BY p."sequence" HAVING count(*)<>1) AND NOT EXISTS(SELECT 1 FROM ordered_participants op WHERE op.game_id=b."id" AND op."score"::BIGINT IS DISTINCT FROM (SELECT COALESCE(sum(p."delta"::BIGINT),0) FROM postings4 p WHERE p.game_id=b."id" AND p."teamId"=op.team_id))
     WHEN b."requestVersion"=5 THEN b."payload" IS NOT NULL AND b."predecessorVersion" IS NULL AND b."predecessorHash" IS NULL AND b."bindingId" IS NULL AND b."bindingHash" IS NULL AND public.int6_enta_exact_keys(b."payload",ARRAY['schemaVersion','rulesVersion','requestVersion','executionFormat','projectId','engine','gameId','admissionId','logicalMatchId','resultVersion','predecessor','terminal','authority','participants','reason','prescribedCount','completedCount','unplayedCount','outcome','scores','winnerParticipantIds','tournamentBinding']) AND public.int5b_json_integer(b."payload"->'prescribedCount',1,36) AND public.int5b_json_integer(b."payload"->'completedCount',0,36) AND public.int5b_json_integer(b."payload"->'unplayedCount',0,36) AND public.int5b_json_integer(b."payload"->'prescribedCount',1,CASE WHEN b."executionFormat" IN ('STANDALONE_LIST','STANDALONE_ACTING') THEN 4 ELSE 36 END) AND (CASE WHEN public.int5b_json_integer(b."payload"->'completedCount',0,36) THEN (b."payload"->>'completedCount')::INTEGER ELSE NULL END)+(CASE WHEN public.int5b_json_integer(b."payload"->'unplayedCount',0,36) THEN (b."payload"->>'unplayedCount')::INTEGER ELSE NULL END)=(CASE WHEN public.int5b_json_integer(b."payload"->'prescribedCount',0,36) THEN (b."payload"->>'prescribedCount')::INTEGER ELSE NULL END) AND ((b."payload"->>'reason'='HOST_ENDED')=((CASE WHEN public.int5b_json_integer(b."payload"->'unplayedCount',0,36) THEN (b."payload"->>'unplayedCount')::INTEGER ELSE NULL END)>0)) AND b."payload"->'schemaVersion'='1'::JSONB AND b."payload"->'requestVersion'='5'::JSONB AND b."payload"->'resultVersion'='1'::JSONB AND b."payload"->>'engine'='ENTA' AND b."payload"->>'rulesVersion'='enta-competitive-1' AND b."payload"->>'gameId'=b."id" AND b."payload"->>'logicalMatchId'=b."id" AND b."payload"->>'admissionId'=b."admissionId" AND b."payload"->>'projectId'=project AND b."payload"->>'executionFormat'=b."executionFormat" AND b."payload"->'predecessor'='null'::JSONB AND b."payload"->'tournamentBinding'='null'::JSONB AND b."resultHash"=public.int6_enta_hash(jsonb_build_object('domain','maydan.enta.result.v1','payload',b."payload")) AND jsonb_typeof(b."payload"->'winnerParticipantIds')='array' AND ((b."payload"->>'outcome'='DECISIVE' AND b."payload"->>'reason'='ALL_ROUNDS' AND (CASE WHEN jsonb_typeof(b."payload"->'winnerParticipantIds')='array' THEN jsonb_array_length(b."payload"->'winnerParticipantIds') ELSE -1 END)=1) OR (b."payload"->>'outcome'='UNRESOLVED_TIE' AND b."payload"->>'reason'='ALL_ROUNDS' AND (CASE WHEN jsonb_typeof(b."payload"->'winnerParticipantIds')='array' THEN jsonb_array_length(b."payload"->'winnerParticipantIds') ELSE -1 END)=0) OR (b."payload"->>'outcome'='HOST_ENDED' AND b."payload"->>'reason'='HOST_ENDED' AND (CASE WHEN jsonb_typeof(b."payload"->'winnerParticipantIds')='array' THEN jsonb_array_length(b."payload"->'winnerParticipantIds') ELSE -1 END)=0)) AND b."payload"->'participants'=to_jsonb(b."teamOrder") AND jsonb_typeof(b."payload"->'scores')='array' AND (CASE WHEN jsonb_typeof(b."payload"->'scores')='array' THEN jsonb_array_length(b."payload"->'scores') ELSE -1 END)=cardinality(b."teamOrder") AND NOT EXISTS(SELECT 1 FROM ordered_participants op WHERE op.game_id=b."id" AND (NOT public.int6_enta_exact_keys(b."payload"->'scores'->((op.ordinal-1)::INTEGER),ARRAY['participantId','score']) OR b."payload"->'scores'->((op.ordinal-1)::INTEGER)->>'participantId' IS DISTINCT FROM op.team_id OR NOT public.int5b_json_integer(b."payload"->'scores'->((op.ordinal-1)::INTEGER)->'score',-2147483648,2147483647))) AND (b."payload"->>'outcome'<>'DECISIVE' OR EXISTS(SELECT 1 FROM ordered_participants op WHERE op.game_id=b."id" AND op.team_id=b."payload"->'winnerParticipantIds'->>0 AND (CASE WHEN public.int5b_json_integer(b."payload"->'scores'->((op.ordinal-1)::INTEGER)->'score',-2147483648,2147483647) THEN (b."payload"->'scores'->((op.ordinal-1)::INTEGER)->>'score')::BIGINT ELSE NULL END)=(SELECT max((CASE WHEN public.int5b_json_integer(v->'score',-2147483648,2147483647) THEN (v->>'score')::BIGINT ELSE NULL END)) FROM jsonb_array_elements(CASE WHEN jsonb_typeof(b."payload"->'scores')='array' THEN b."payload"->'scores' ELSE '[]'::JSONB END) v))) AND (b."payload"->>'outcome'='HOST_ENDED' OR (b."payload"->>'outcome'='DECISIVE' AND (SELECT count(*) FROM jsonb_array_elements(CASE WHEN jsonb_typeof(b."payload"->'scores')='array' THEN b."payload"->'scores' ELSE '[]'::JSONB END) v WHERE (CASE WHEN public.int5b_json_integer(v->'score',-2147483648,2147483647) THEN (v->>'score')::BIGINT ELSE NULL END)=(SELECT max((CASE WHEN public.int5b_json_integer(z->'score',-2147483648,2147483647) THEN (z->>'score')::BIGINT ELSE NULL END)) FROM jsonb_array_elements(CASE WHEN jsonb_typeof(b."payload"->'scores')='array' THEN b."payload"->'scores' ELSE '[]'::JSONB END) z))=1) OR (b."payload"->>'outcome'='UNRESOLVED_TIE' AND (SELECT count(*) FROM jsonb_array_elements(CASE WHEN jsonb_typeof(b."payload"->'scores')='array' THEN b."payload"->'scores' ELSE '[]'::JSONB END) v WHERE (CASE WHEN public.int5b_json_integer(v->'score',-2147483648,2147483647) THEN (v->>'score')::BIGINT ELSE NULL END)=(SELECT max((CASE WHEN public.int5b_json_integer(z->'score',-2147483648,2147483647) THEN (z->>'score')::BIGINT ELSE NULL END)) FROM jsonb_array_elements(CASE WHEN jsonb_typeof(b."payload"->'scores')='array' THEN b."payload"->'scores' ELSE '[]'::JSONB END) z))>1)) AND EXISTS(SELECT 1 FROM public."RoundAuthorityEvent" e JOIN public."GameEvent" legacy ON (legacy."gameId",legacy."sequence",legacy."actorFirebaseIdentityId")=(e."gameId",e."sequence",owner_id) WHERE e."gameId"=b."id" AND e."id"=b."terminalEventId" AND e."id"=b."authorityEventId" AND e."sequence"=b."terminalRevision" AND e."type"='FINISH' AND e."ownerIdentityId"=owner_id AND e."authorityKind"='HOST' AND e."authorityGrantId" IS NULL AND e."authorityGeneration" IS NULL AND e."assignmentId" IS NULL AND e."systemOperation" IS NULL AND e."pauseReason" IS NULL AND e."roundId" IS NULL AND legacy."type"='FINISH' AND legacy."commandId"=e."commandId" AND legacy."intentHash"=e."intentHash" AND b."payload"->'terminal'=jsonb_build_object('eventId',e."id",'revision',e."sequence") AND b."payload"->'authority'=jsonb_build_object('eventId',e."id",'kind','HOST','correctionReason',NULL))
     ELSE FALSE END,FALSE) AS valid
  FROM owned_base b JOIN terminals t ON t.game_id=b."id"
 )
 SELECT CASE WHEN count(*)=1 AND bool_and(valid) THEN jsonb_build_object('schemaVersion',1,'id',min("id"),'physicalProtocol',min("requestVersion"),'mode',min("mode"),'executionFormat',min("executionFormat"),'retainedRulesProfile',min("rules"),'reason',min(original_reason),'unplayedCount',(min(original_unplayed::TEXT))::JSONB,'isTie',bool_and(original_tie),'teams',(min(teams::TEXT))::JSONB) ELSE NULL END INTO output FROM reconstructed;
 IF output IS NULL THEN RAISE EXCEPTION 'RESULT_UNAVAILABLE'; END IF; RETURN output;
END $$;


CREATE FUNCTION public.pro311_enta_history(ns TEXT, project TEXT, uid TEXT, p_window JSONB) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$
DECLARE owner_id TEXT; n INTEGER; upper_at TIMESTAMP(3); upper_id TEXT; before_at TIMESTAMP(3); before_id TEXT; output JSONB;
BEGIN
 owner_id:=public.int6_enta_identity(ns,project,uid)->>'id';
 PERFORM public.e3_comp_history_utc_gate();
 IF NOT public.int6_enta_exact_keys(p_window,ARRAY['filters','limit','upper','before']) OR NOT public.int6_enta_exact_keys(p_window->'filters',ARRAY['mode','format','rules','status']) OR NOT public.int5b_json_integer(p_window->'limit',1,50) OR (p_window->'upper'='null'::JSONB) IS DISTINCT FROM (p_window->'before'='null'::JSONB) THEN RAISE EXCEPTION 'INVALID_HISTORY_QUERY'; END IF;
 IF p_window->'filters'->'mode' NOT IN ('null'::JSONB,'"CLASSIC"'::JSONB,'"KIDS"'::JSONB,'"LIST"'::JSONB,'"ACTING"'::JSONB)
 OR p_window->'filters'->'format' NOT IN ('null'::JSONB,'"TIER_BOARD"'::JSONB,'"MIXED_BOARD"'::JSONB,'"STANDALONE_LIST"'::JSONB,'"STANDALONE_ACTING"'::JSONB)
 OR p_window->'filters'->'rules' NOT IN ('null'::JSONB,'"enta-classic-2"'::JSONB,'"enta-classic-3"'::JSONB,'"enta-kids-3"'::JSONB,'"enta-format-1"'::JSONB,'"enta-competitive-1"'::JSONB)
 OR p_window->'filters'->'status' NOT IN ('null'::JSONB,'"ACTIVE"'::JSONB,'"FINISHED"'::JSONB) THEN RAISE EXCEPTION 'INVALID_HISTORY_QUERY'; END IF;
 n:=(p_window->>'limit')::INTEGER;
 IF p_window->'upper'<>'null'::JSONB THEN
  IF jsonb_typeof(p_window->'upper') IS DISTINCT FROM 'object' OR jsonb_typeof(p_window->'before') IS DISTINCT FROM 'object'
   OR jsonb_typeof(p_window->'upper'->'createdAt') IS DISTINCT FROM 'string' OR jsonb_typeof(p_window->'upper'->'id') IS DISTINCT FROM 'string'
   OR jsonb_typeof(p_window->'before'->'createdAt') IS DISTINCT FROM 'string' OR jsonb_typeof(p_window->'before'->'id') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'INVALID_HISTORY_CURSOR'; END IF;
  IF NOT public.int6_enta_exact_keys(p_window->'upper',ARRAY['createdAt','id']) OR NOT public.int6_enta_exact_keys(p_window->'before',ARRAY['createdAt','id']) OR p_window->'upper'->>'id' !~ '^[A-Za-z0-9_-]{1,128}$' OR p_window->'before'->>'id' !~ '^[A-Za-z0-9_-]{1,128}$' OR p_window->'upper'->>'createdAt' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$' OR p_window->'before'->>'createdAt' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$' THEN RAISE EXCEPTION 'INVALID_HISTORY_CURSOR'; END IF;
  upper_at:=(p_window->'upper'->>'createdAt')::TIMESTAMPTZ AT TIME ZONE 'UTC'; upper_id:=p_window->'upper'->>'id'; before_at:=(p_window->'before'->>'createdAt')::TIMESTAMPTZ AT TIME ZONE 'UTC'; before_id:=p_window->'before'->>'id';
  IF to_char(upper_at,'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') IS DISTINCT FROM p_window->'upper'->>'createdAt' OR to_char(before_at,'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') IS DISTINCT FROM p_window->'before'->>'createdAt' THEN RAISE EXCEPTION 'INVALID_HISTORY_CURSOR'; END IF;
  IF (before_at,before_id COLLATE "C")>(upper_at,upper_id COLLATE "C") THEN RAISE EXCEPTION 'INVALID_HISTORY_CURSOR'; END IF;
 END IF;
 WITH all_owned AS MATERIALIZED (
  SELECT g."id",g."firebaseIdentityId",g."admissionId",g."catalogReleaseId",g."gameFormat",g."executionFormat",g."mode",g."status",g."createdAt",g."finishedAt",g."winnerTeamId",g."isTie",
   a."id" AS admission_join,a."engine",a."state" AS admission_state,a."requestVersion",rt."gameId" AS runtime_join,rt."version",rt."state" AS runtime_state,rt."setup",rt."setupHash",rt."teamOrder",rt."resultReason",rt."unplayedCount",p."rules",pin."clientBinding",pin."clientHash",
   result."payload",result."resultHash",result."terminalRevision",result."terminalEventId",result."authorityEventId",result."predecessorVersion",result."predecessorHash",result."bindingId",result."bindingHash"
  FROM public."Game" g
  LEFT JOIN public."Admission" a ON (a."id",a."firebaseIdentityId")=(g."admissionId",g."firebaseIdentityId")
  LEFT JOIN public."GameRuntime" rt ON rt."gameId"=g."id"
  LEFT JOIN public."E3PhysicalProfile" p ON (p."protocol",p."format",p."mode")=(a."requestVersion",g."executionFormat",g."mode")
  LEFT JOIN public."EntaExecutionPin" pin ON (pin."gameId",pin."firebaseIdentityId")=(g."id",g."firebaseIdentityId")
  LEFT JOIN public."EngineMatchResult" result ON (result."gameId",result."ownerIdentityId",result."admissionId",result."resultVersion")=(g."id",g."firebaseIdentityId",g."admissionId",1)
  WHERE g."firebaseIdentityId"=owner_id
 ), eligible AS MATERIALIZED (
  SELECT b.* FROM all_owned b WHERE (p_window->'filters'->>'mode' IS NULL OR b."mode"=p_window->'filters'->>'mode' OR b."rules" IS NULL)
   AND (p_window->'filters'->>'format' IS NULL OR b."executionFormat"=p_window->'filters'->>'format' OR b."rules" IS NULL)
   AND (p_window->'filters'->>'rules' IS NULL OR b."rules"=p_window->'filters'->>'rules' OR b."rules" IS NULL)
 ), upper_bound AS MATERIALIZED (
  SELECT COALESCE(upper_at,(SELECT e."createdAt" FROM eligible e WHERE (p_window->'filters'->>'status' IS NULL OR e."status"=p_window->'filters'->>'status' OR e."status" NOT IN ('ACTIVE','FINISHED')) ORDER BY e."createdAt" DESC,e."id" COLLATE "C" DESC LIMIT 1)) AS at,
   COALESCE(upper_id,(SELECT e."id" FROM eligible e WHERE (p_window->'filters'->>'status' IS NULL OR e."status"=p_window->'filters'->>'status' OR e."status" NOT IN ('ACTIVE','FINISHED')) ORDER BY e."createdAt" DESC,e."id" COLLATE "C" DESC LIMIT 1)) AS id
 ), selected AS MATERIALIZED (
  SELECT e."id",e."createdAt" FROM eligible e CROSS JOIN upper_bound u
  WHERE (p_window->'filters'->>'status' IS NULL OR e."status"=p_window->'filters'->>'status' OR e."status" NOT IN ('ACTIVE','FINISHED')) AND (e."createdAt",e."id" COLLATE "C")<=(u.at,u.id COLLATE "C") AND (before_at IS NULL OR (e."createdAt",e."id" COLLATE "C")<(before_at,before_id COLLATE "C"))
  ORDER BY e."createdAt" DESC,e."id" COLLATE "C" DESC LIMIT n+1
 ), anchors AS MATERIALIZED (
  SELECT e."id",e."createdAt",'upper'::TEXT AS kind FROM eligible e CROSS JOIN upper_bound u WHERE (e."createdAt",e."id")=(u.at,u.id)
  UNION ALL SELECT e."id",e."createdAt",'before'::TEXT FROM eligible e WHERE before_at IS NOT NULL AND (e."createdAt",e."id")=(before_at,before_id)
 ), work_ids AS MATERIALIZED (SELECT "id" FROM selected UNION SELECT "id" FROM anchors),
 owned_base AS MATERIALIZED (SELECT e.* FROM all_owned e JOIN work_ids w ON w."id"=e."id"),
 ordered_participants AS MATERIALIZED (
  SELECT b."id" AS game_id,o.team_id,o.ordinal,t."id" AS joined_team,t."name",t."score",b."setup"->'teams'->((o.ordinal-1)::INTEGER)->>'name' AS original_name
  FROM owned_base b CROSS JOIN LATERAL unnest(b."teamOrder") WITH ORDINALITY o(team_id,ordinal)
  LEFT JOIN public."Team" t ON (t."gameId",t."id")=(b."id",o.team_id)
 ), adjudications23 AS MATERIALIZED (
  SELECT b."id" AS game_id,e."questionId",e."teamId",e."ruling",e."sequence",q."id" AS joined_question,m."questionRevisionId" AS joined_membership,qr."id" AS joined_revision,qr."points",qr."engine",qr."mode" AS revision_mode,qr."modality",seal."questionRevisionId" AS joined_seal
  FROM owned_base b JOIN public."GameEvent" e ON e."gameId"=b."id" AND e."type"='ADJUDICATE'
  LEFT JOIN public."GameQuestion" q ON (q."gameId",q."id")=(e."gameId",e."questionId") AND q."catalogReleaseId"=b."catalogReleaseId"
  LEFT JOIN public."CatalogReleaseQuestion" m ON (m."catalogReleaseId",m."questionRevisionId")=(q."catalogReleaseId",q."questionRevisionId")
  LEFT JOIN public."QuestionRevision" qr ON (qr."id",qr."contentHash")=(m."questionRevisionId",m."questionContentHash")
  LEFT JOIN public."QuestionRevisionSeal" seal ON (seal."questionRevisionId",seal."contentHash")=(qr."id",qr."contentHash")
 ), postings4 AS MATERIALIZED (
  SELECT b."id" AS game_id,p."id",p."teamId",p."delta",p."before",p."after",p."rulesVersion",e."id" AS joined_event,e."sequence",p."roundId",p."itemId",e."roundId" AS event_round,rr."id" AS joined_round,ri."itemId" AS joined_item,
   lag(p."after") OVER (PARTITION BY b."id",p."teamId" ORDER BY e."sequence",p."id" COLLATE "C") AS previous_after
  FROM owned_base b JOIN public."RoundScorePosting" p ON p."gameId"=b."id"
  LEFT JOIN public."RoundAuthorityEvent" e ON (e."id",e."gameId",e."roundId")=(p."eventId",p."gameId",p."roundId") LEFT JOIN public."GameRound" rr ON (rr."gameId",rr."id")=(p."gameId",p."roundId") LEFT JOIN public."RoundItemPin" ri ON (ri."roundId",ri."itemId")=(p."roundId",p."itemId")
 ), terminals AS MATERIALIZED (
  SELECT b."id" AS game_id,
   (SELECT count(*) FROM public."GameEvent" e WHERE e."gameId"=b."id" AND e."type"='FINISH' AND e."actorFirebaseIdentityId"=owner_id) AS legacy_count,
   (SELECT max(e."sequence") FROM public."GameEvent" e WHERE e."gameId"=b."id" AND e."type"='FINISH' AND e."actorFirebaseIdentityId"=owner_id) AS legacy_sequence,
   (SELECT count(*) FROM public."RoundAuthorityEvent" e WHERE e."gameId"=b."id" AND e."type"='FINISH' AND e."ownerIdentityId"=owner_id AND e."authorityKind"='HOST' AND e."authorityGrantId" IS NULL AND e."authorityGeneration" IS NULL AND e."assignmentId" IS NULL AND e."systemOperation" IS NULL AND e."pauseReason" IS NULL AND e."roundId" IS NULL) AS authority_count,
   (SELECT max(e."sequence") FROM public."RoundAuthorityEvent" e WHERE e."gameId"=b."id" AND e."type"='FINISH' AND e."ownerIdentityId"=owner_id AND e."authorityKind"='HOST' AND e."authorityGrantId" IS NULL AND e."authorityGeneration" IS NULL AND e."assignmentId" IS NULL AND e."systemOperation" IS NULL AND e."pauseReason" IS NULL AND e."roundId" IS NULL) AS authority_sequence
  FROM owned_base b
 ), reconstructed AS MATERIALIZED (
  SELECT b.*,t.legacy_count,t.legacy_sequence,t.authority_count,t.authority_sequence,
   CASE WHEN b."status"='ACTIVE' THEN NULL WHEN b."requestVersion"=5 THEN b."payload"->>'reason' WHEN b."requestVersion"=4 AND b."resultReason"='ALL_QUESTIONS_PLAYED' THEN 'ALL_ROUNDS' ELSE b."resultReason" END AS original_reason,
   CASE WHEN b."status"='ACTIVE' THEN NULL WHEN b."requestVersion"=5 THEN b."payload"->'unplayedCount' ELSE to_jsonb(b."unplayedCount") END AS original_unplayed,
   CASE WHEN b."status"='ACTIVE' THEN NULL WHEN b."requestVersion"=5 THEN b."payload"->>'outcome'='UNRESOLVED_TIE' ELSE b."isTie" END AS original_tie,
   (SELECT jsonb_agg(jsonb_build_object('name',op.original_name,'score',CASE WHEN b."status"='ACTIVE' THEN op."score" WHEN b."requestVersion"=5 THEN (CASE WHEN public.int5b_json_integer(b."payload"->'scores'->((op.ordinal-1)::INTEGER)->'score',-2147483648,2147483647) THEN (b."payload"->'scores'->((op.ordinal-1)::INTEGER)->>'score')::INTEGER ELSE NULL END) WHEN b."requestVersion" IN (2,3) THEN (SELECT COALESCE(sum(a."points"::BIGINT),0) FROM adjudications23 a WHERE a.game_id=b."id" AND a."ruling"='CORRECT' AND a."teamId"=op.team_id) ELSE (SELECT COALESCE(sum(p."delta"::BIGINT),0) FROM postings4 p WHERE p.game_id=b."id" AND p."teamId"=op.team_id) END,'winner',CASE WHEN b."status"='ACTIVE' THEN FALSE WHEN b."requestVersion"=5 THEN (b."payload"->'winnerParticipantIds') ? op.team_id ELSE op."score"=(SELECT max(t2."score") FROM public."Team" t2 WHERE t2."gameId"=b."id") END) ORDER BY op.ordinal) FROM ordered_participants op WHERE op.game_id=b."id") AS teams,
   COALESCE(b.admission_join IS NOT NULL AND b.runtime_join IS NOT NULL AND b."gameFormat"='FIREBASE_PINNED' AND b."engine"='ENTA' AND b.admission_state='COMMITTED' AND (b."requestVersion",b."mode",b."executionFormat",b."rules") IN ((2,'CLASSIC','TIER_BOARD','enta-classic-2'),(3,'CLASSIC','TIER_BOARD','enta-classic-3'),(3,'KIDS','TIER_BOARD','enta-kids-3'),(4,'CLASSIC','MIXED_BOARD','enta-format-1'),(4,'LIST','STANDALONE_LIST','enta-format-1'),(4,'ACTING','STANDALONE_ACTING','enta-format-1'),(5,'CLASSIC','TIER_BOARD','enta-competitive-1'),(5,'CLASSIC','MIXED_BOARD','enta-competitive-1'),(5,'LIST','STANDALONE_LIST','enta-competitive-1'),(5,'ACTING','STANDALONE_ACTING','enta-competitive-1')) AND b."status" IN ('ACTIVE','FINISHED') AND ((b."status"='ACTIVE' AND ((b."requestVersion" IN (2,3) AND b.runtime_state IN ('BOARD','QUESTION_OPEN','REVEALED')) OR (b."requestVersion" IN (4,5) AND b.runtime_state='BOARD')) AND b."finishedAt" IS NULL) OR (b."status"='FINISHED' AND b.runtime_state='FINISHED' AND b."finishedAt" IS NOT NULL)) AND cardinality(b."teamOrder") BETWEEN 2 AND 4 AND jsonb_typeof(b."setup"->'teams')='array' AND (CASE WHEN jsonb_typeof(b."setup"->'teams')='array' THEN jsonb_array_length(b."setup"->'teams') ELSE -1 END)=cardinality(b."teamOrder") AND b."setupHash"=public.int6_enta_hash(b."setup") AND (b."mode" NOT IN ('KIDS','LIST','ACTING') OR cardinality(b."teamOrder")=2)
    AND (SELECT count(*) FROM ordered_participants op WHERE op.game_id=b."id")=cardinality(b."teamOrder") AND (SELECT count(DISTINCT op.team_id) FROM ordered_participants op WHERE op.game_id=b."id")=cardinality(b."teamOrder") AND (SELECT count(*) FROM public."Team" x WHERE x."gameId"=b."id")=cardinality(b."teamOrder") AND NOT EXISTS(SELECT 1 FROM ordered_participants op WHERE op.game_id=b."id" AND (op.joined_team IS NULL OR op."name" IS DISTINCT FROM op.original_name OR public.int6_enta_valid_text(to_jsonb(op.original_name),2,22) IS NOT TRUE))
