 OR jsonb_typeof(rr."state"->'state') IS DISTINCT FROM 'string' OR COALESCE(rr."state"->>'state' NOT IN ('READY','RUNNING','PAUSED','RESOLVED'),TRUE)
 OR public.int5b_json_integer(rr."state"->'version',0,2000000000) IS NOT TRUE OR jsonb_typeof(rr."state"->'revealed') IS DISTINCT FROM 'boolean' OR jsonb_typeof(rr."state"->'consumed') IS DISTINCT FROM 'array'
