)) AND b."unplayedCount"=(SELECT count(*) FROM public."GameRound" rr WHERE rr."gameId"=b."id" AND rr."state"->>'state'<>'RESOLVED') AND b."isTie"=((SELECT count(*) FROM public."Team" x WHERE x."gameId"=b."id" AND x."score"=(SELECT max(z."score") FROM public."Team" z WHERE z."gameId"=b."id"))>1) AND b."winnerTeamId" IS NOT DISTINCT FROM (SELECT CASE WHEN count(*)=1 THEN min(x."id") ELSE NULL END FROM public."Team" x WHERE x."gameId"=b."id" AND x."score"=(SELECT max(z."score") FROM public."Team" z WHERE z."gameId"=b."id")) AND NOT EXISTS(SELECT 1 FROM postings4 p WHERE p.game_id=b."id" AND (p.joined_event IS NULL OR p.joined_round IS NULL OR (p."itemId" IS NOT NULL AND p.joined_item IS NULL) OR p."sequence">=t.authority_sequence OR p."rulesVersion"<>'enta-format-1' OR p."before"::BIGINT IS DISTINCT FROM COALESCE(p.previous_after::BIGINT,0) OR p."after"::BIGINT-p."before"::BIGINT<>p."delta"::BIGINT OR NOT EXISTS(SELECT 1 FROM ordered_participants op WHERE op.game_id=b."id" AND op.team_id=p."teamId"))) AND NOT EXISTS(SELECT 1 FROM postings4 p WHERE p.game_id=b."id" GROUP BY p."sequence" HAVING count(*)<>1) AND NOT EXISTS(SELECT 1 FROM ordered_participants op WHERE op.game_id=b."id" AND op."score"::BIGINT IS DISTINCT FROM (SELECT COALESCE(sum(p."delta"::BIGINT),0) FROM postings4 p WHERE p.game_id=b."id" AND p."teamId"=op.team_id))
