namentBinding'='null'::JSONB AND b."resultHash"=public.int6_enta_hash(jsonb_build_object('domain','maydan.enta.result.v1','payload',b."payload")) AND jsonb_typeof(b."payload"->'winnerParticipantIds')='array' AND ((b."payload"->>'outcome'='DECISIVE' AND b."payload"->>'reason'='ALL_ROUNDS' AND (CASE WHEN jsonb_typeof(b."payload"->'winnerParticipantIds')='array' THEN jsonb_array_length(b."payload"->'winnerParticipantIds') ELSE -1 END)=1) OR (b."payload"->>'outcome'='UNRESOLVED_TIE' AND b."payload"->>'reason'='ALL_ROUNDS' AND (CASE WHEN jsonb_typeof(b."payload"->'winnerParticipantIds')='array' THEN jsonb_array_length(b."payload"->'winnerParticipantIds') ELSE -1 END)=0) OR (b."payload"->>'outcome'='HOST_ENDED' AND b."payload"->>'reason'='HOST_ENDED' AND (CASE WHEN jsonb_typeof(b."payload"->'winnerParticipantIds')='array' THEN jsonb_array_length(b."payload"->'winnerParticipantIds') ELSE -1 END)=0)) AND b."payload"->'participants'=to_jsonb(b."teamOrder") AND jsonb_typeof(b."payload"->'scores')='array' AND (CASE WHEN jsonb_typeof(b."payload"->'scores')='array' THEN jsonb_array_length(b."payload"->'scores') ELSE -1 END)=cardinality(b."teamOrder") AND NOT EXISTS(SELECT 1 FROM ordered_participants op WHERE op.game_id=b."id" AND (NOT public.int6_enta_exact_keys(b."payload"->'scores'->((op.ordinal-1)::INTEGER),ARRAY['participantId','score']) OR b."payload"->'scores'->((op.ordinal-1)::INTEGER)->>'participantId' IS DISTINCT FROM op.team_id OR NOT public.int5b_json_integer(b."payload"->'scores'->((op.ordinal-1)::INTEGER)->'score',-2147483648,2147483647))) AND (b."payload"->>'outcome'<>'DECISIVE' OR EXISTS(SELECT 1 FROM ordered_participants op WHERE op.game_id=b."id" AND op.team_id=b."payload"->'winnerParticipantIds'->>0 AND (CASE WHEN public.int5b_json_integer(b."payload"->'scores'->((op.ordinal-1)::INTEGER)->'score',-2147483648,2147483647) THEN (b."payload"->'scores'->((op.ordinal-1)::INTEGER)->>'score')::BIGINT ELSE NULL END)=(SELECT max((CASE WHEN public.int5b_json_integer(v->'s