 , metadata AS MATERIALIZED (
  SELECT r."id",r."createdAt",r.valid,jsonb_build_object('id',r."id",'admissionProtocol',r."requestVersion",'mode',r."mode",'executionFormat',r."executionFormat",'retainedRulesProfile',r."rules",'status',r."status",'createdAt',to_char(r."createdAt",'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'finishedAt',CASE WHEN r."finishedAt" IS NULL THEN NULL ELSE to_char(r."finishedAt",'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END,'teams',(SELECT jsonb_agg(jsonb_build_object('name',x->'name','score',x->'score') ORDER BY ord) FROM jsonb_array_elements(r.teams) WITH ORDINALITY t(x,ord)),'summary',CASE WHEN r."status"='ACTIVE' THEN NULL ELSE jsonb_build_object('reason',r.original_reason,'unplayedCount',r.original_unplayed,'isTie',r.original_tie) END) AS row
