 )
 SELECT CASE WHEN upper_at IS NOT NULL AND ((SELECT count(*) FROM anchors WHERE kind='upper')<>1 OR (SELECT count(*) FROM anchors WHERE kind='before')<>1) THEN jsonb_build_object('outcome','INVALID_ANCHOR')
 WHEN EXISTS(SELECT 1 FROM metadata WHERE valid IS DISTINCT FROM TRUE) OR (SELECT count(*) FROM metadata)<>(SELECT count(*) FROM work_ids) THEN jsonb_build_object('outcome','DATA_UNAVAILABLE')
 ELSE jsonb_build_object('outcome','OK','upper',(SELECT CASE WHEN u.id IS NULL THEN NULL ELSE jsonb_build_object('createdAt',to_char(u.at,'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'id',u.id) END FROM upper_bound u),'resolvedUpper',CASE WHEN upper_at IS NULL THEN NULL ELSE p_window->'upper' END,'resolvedBefore',CASE WHEN before_at IS NULL THEN NULL ELSE p_window->'before' END,'rows',COALESCE((SELECT jsonb_agg(m.row ORDER BY s."createdAt" DESC,s."id" COLLATE "C" DESC) FROM selected s JOIN metadata m ON m."id"=s."id"),'[]'::JSONB),'anchorRows',COALESCE((SELECT jsonb_agg(jsonb_build_object('kind',a.kind,'row',m.row) ORDER BY CASE a.kind WHEN 'upper' THEN 0 ELSE 1 END) FROM anchors a JOIN metadata m ON m."id"=a."id"),'[]'::JSONB)) END INTO output;
 RETURN output;
